  // rather than a broken `/overlay/undefined` preview URL.
  return (
    <Editor
      types={types}
      overlayToken={overlay?.token ?? null}
      overlayUrl={overlay ? `${base}/overlay/${overlay.token}` : null}
      samples={samples}
    />
  );
}
